// Turns a backend event into a readable summary. Add Gmail / Telegram / Google Sheets after this node.
const body = $input.first().json.body ?? $input.first().json;
const d = body.data ?? {};
const inr = (n) => 'INR ' + Math.round(Number(n) || 0).toLocaleString('en-IN');
const label = body.event === 'trip_saved' ? 'Trip saved' : 'Trip generated';
return [{ json: {
  event: body.event,
  sent_at: body.sent_at,
  headline: `${label}: ${d.destination} (${d.start_date} to ${d.end_date}), ${d.travelers} traveller(s)`,
  budget: inr(d.budget),
  estimated_total: inr(d.estimated_total),
  over_budget: !!d.over_budget,
  model: d.model,
  trip_id: d.trip_id ?? null,
}}];
